const m=n=>{const r=[],i=/@(\w+)\s*\{\s*([^,]+),\s*([\s\S]*?)\s*\}[\n\r]/g;let t;for(;(t=i.exec(n))!==null;){const l=t[1].toLowerCase(),a=t[2].trim(),c=t[3],e={},u=/(\w+)\s*=\s*\{([^}]*)\}/g;let s;for(;(s=u.exec(c))!==null;)e[s[1].toLowerCase()]=s[2].trim();const h=e.title||"";let o=e.author||e.authors||"Unknown";o=o.replace(/\s+/g," ").trim();const w=e.year||"",b=e.journal||e.publisher||e.booktitle||"",g={id:`bib_${Date.now()}_${Math.random().toString(36).substr(2,6)}`,title:h,authors:o,year:parseInt(w)||new Date().getFullYear(),journal:b,methodology:"literature review",keyFindings:["Imported from BibTeX"],type:l,bibKey:a};r.push(g)}return r};export{m as parseBibTeX};
